#!/usr/bin/env python3
# Derives schemas/motif-graph-1.schema.json from the node registry and adds the "graph" data to motif-project.schema.json.
# python3 src-v9/build/gen_schemas.py <schemas dir>      (run from the repository root; needs node)
import json, sys, os, subprocess
d = sys.argv[1]
root = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
reg = json.loads(subprocess.check_output(['node', os.path.join(root, 'tests/v9/dump-registry.mjs')], text=True))
def prop(p):
    t = p['type']
    if t == 'range': return {'type': 'number', 'minimum': p['min'], 'maximum': p['max'], 'default': p['def'], 'description': p['label']}
    if t == 'int': return {'type': 'integer', 'minimum': p['min'], 'maximum': p['max'], 'default': p['def'], 'description': p['label']}
    if t == 'select': return {'enum': p['options'], 'default': p['def'], 'description': p['label']}
    return {'type': 'boolean', 'default': p['def'], 'description': p['label']}
variants = []
for name, t in reg['types'].items():
    variants.append({'type': 'object', 'required': ['id', 'type'], 'additionalProperties': False, 'description': t['name'] + ': ' + t['hint'],
        'properties': {'id': {'type': 'string', 'pattern': '^(stage|g[a-z0-9]{1,10})$'}, 'type': {'const': name}, 'on': {'type': 'boolean', 'default': True},
                       'ref': {'type': 'string', 'description': 'id of a field node (weights an effector or deformer; for a field: the field combined with it)'},
                       'params': {'type': 'object', 'additionalProperties': False, 'properties': {k: prop(p) for k, p in t['params'].items()}}}})
variants.append({'type': 'object', 'required': ['id', 'type', 'unknown'], 'description': 'A node type this version of Motif does not know (from a newer Motif): kept, never drawn.', 'properties': {'id': {'type': 'string'}, 'type': {'type': 'string'}, 'on': {'type': 'boolean'}, 'unknown': {'const': True}, 'params': {'type': 'object'}}})
schema = {'$schema': 'https://json-schema.org/draft/2020-12/schema', '$id': 'https://motif.local/schemas/motif-graph-1.schema.json', 'title': 'MotifGraph (motif-graph@1)',
  '$comment': 'GENERATED by src-v9/build/gen_schemas.py from the node registry in the graph module. Do not edit by hand.',
  'description': 'The "graph" of a layer (layer scope) or of a project (composite scope): a data-only node stack. Stage (exactly one, first), Cloner (at most one), Fields, Effectors, Deformers. Parameters are project channels addressed M:<layerId or @>:<nodeId>:<key>.',
  'type': 'object', 'additionalProperties': False, 'required': ['v', 'nodes'],
  'properties': {'v': {'const': reg['version']}, 'on': {'type': 'boolean', 'default': True}, 'place': {'enum': ['pre', 'post'], 'default': 'pre', 'description': 'Composite scope only: before or after the finishing stack.'},
                 'nodes': {'type': 'array', 'maxItems': reg['maxNodes'] + 4, 'items': {'anyOf': variants}}}}
json.dump(schema, open(os.path.join(d, 'motif-graph-1.schema.json'), 'w'), indent=1); open(os.path.join(d, 'motif-graph-1.schema.json'), 'a').write('\n')
pj = os.path.join(d, 'motif-project.schema.json'); s = json.load(open(pj))
ref = {'$ref': 'motif-graph-1.schema.json', 'description': 'MotifGraph stack of this layer (layer scope).'}
s['$defs']['layer']['properties']['graph'] = ref
s['properties']['graph'] = {'$ref': 'motif-graph-1.schema.json', 'description': 'MotifGraph stack of the whole composite (composite scope).'}
txt = json.dumps(s, indent=1, ensure_ascii=False)
OLD = 'G:[^:]+:.+)$'
if 'M:[^:]+:[^:]+:.+' not in txt: assert OLD in txt, 'project schema key pattern changed'; txt = txt.replace(OLD, 'G:[^:]+:.+|M:[^:]+:[^:]+:.+)$')
open(pj, 'w').write(txt + '\n')
print('ok:', len(reg['types']), 'node types')
